//! How a FITS-WCS write describes a 1-D axis that is linear, nearly linear
//! or logarithmic in pixel coordinates, against C: `OtherAxes` (fitschan.c)
//! uses a linear description when `IsMapLinear` finds the axis linear, a
//! `-LOG` one when `LogAxis` finds it logarithmic, and `MakeIntWorld` then
//! decides whether the result is linear enough to write.
//!
//! Each FrameSet maps a 1-D GRID Frame to a 1-D Frame with a MathMap, and is
//! written with NAXIS1 set. Compared with C: the value the write returns and
//! the cards written. `fitschan_linear_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/fitschan_linear_probe.c`.

#[rustfmt::skip]
#[path = "fitschan_linear_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{BasicFrameBuilder, FrameRef, FrameSet};
use starlink_ast::mappings::MathMap;
use starlink_ast::{AnyObject, Channel, Encoding, FitsChan};

/// The value the write returns and the cards written.
fn written(fwd: &str, inv: &str, naxis1: i32) -> (i32, Vec<String>) {
    let grid = BasicFrameBuilder::new(1).domain("GRID").build().unwrap();
    let wcs = BasicFrameBuilder::new(1).domain("X").build().unwrap();
    let map = MathMap::new(1, 1, &[fwd], &[inv]).unwrap();
    let mut fs = FrameSet::new(Box::new(grid));
    fs.add_frame(FrameRef::Base, Box::new(map), Box::new(wcs))
        .unwrap();
    let mut fc = FitsChan::new().unwrap();
    fc.set_encoding(Encoding::FitsWcs);
    fc.put_fits(&format!("NAXIS1  = {naxis1}"), false).unwrap();
    let ret = fc.write(&AnyObject::FrameSet(fs)).map_or(0, |n| n as i32);
    fc.clear_card().unwrap();
    let mut cards = Vec::new();
    while let Some(card) = fc.find_fits("%f", true).unwrap() {
        cards.push(card);
    }
    (ret, cards)
}

#[test]
fn axis_descriptions_match_c() {
    let mut failed = Vec::new();
    for &(name, fwd, inv, naxis1, ret, cards) in cases::CASES {
        let got = written(fwd, inv, naxis1);
        let want = (ret, cards.iter().map(|c| c.to_string()).collect::<Vec<_>>());
        if got != want {
            failed.push(format!("{name}:\n--- rust\n{got:#?}\n--- C\n{want:#?}"));
        }
    }
    assert!(failed.is_empty(), "{}", failed.join("\n"));
}
